// CSD_RATIONALE_BEGIN
// The strategy tracks the visible output (`generated`), whether generation is
// currently inside a constrained arithmetic span, and the active constrained
// contents (`currentConstrainedOut`). It appends one task-guidance block up
// front instructing the model to place arithmetic computations inside visible
// `<< >>` delimiters.
// 
// Outside constrained spans, the strategy generates freely one token at a time.
// If the model emits `<<`, the strategy enters constrained mode and resets the
// constrained prefix to the empty valid prefix. Inside a constrained span, it
// closes immediately when the parser reports completeness; otherwise it uses an
// adaptive constrained step with caller-supplied token groups as a soft bias
// while keeping parser validity as the hard authority. This supports the task
// by allowing natural step-by-step prose outside spans and parser-valid
// arithmetic content inside spans.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Outside-span branch: if the sampled token is ordinary free text, the
//   implication remains vacuous because `insideConstrainedOut` stays false. If
//   the token is `<<`, we set `insideConstrainedOut := true` and
//   `currentConstrainedOut := []`; the precondition gives `parser.IsValidPrefix([])`.
// - Complete-prefix branch: `CloseConstrainedSpan` exits constrained mode and
//   clears the active constrained prefix, so the implication becomes vacuous.
// - Active constrained branch: `AdaptiveConstrainedStep` returns either EOS or a
//   parser-valid next token. On EOS we break without changing the state; on a
//   non-EOS token, `AppendConstrainedToken` extends `currentConstrainedOut` with
//   that valid token, preserving `parser.IsValidPrefix(currentConstrainedOut)`.
// 
// progress:
// - Outside-span branch: `UnconstrainedStep` consumes 1 token-step. If the token
//   is non-EOS, visible output grows by at most 1 token, so
//   `|generated| <= |generatedPrefix| + steps` is preserved after `steps := steps + 1`.
// - Complete-prefix branch: `CloseConstrainedSpan` consumes 1 token-step and
//   appends at most the visible closing delimiter, so visible growth is at most
//   the consumed budget.
// - Active constrained branch: `AdaptiveConstrainedStep` consumes 1 token-step.
//   If it returns EOS, no visible token is appended; otherwise
//   `AppendConstrainedToken` appends exactly one visible token. Thus visible
//   growth is at most the consumed token budget in either case.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve the math word problem step by step. Write each arithmetic computation inside visible << and >> delimiters.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Step-by-step math CSD with explicit arithmetic spans. The strategy tracks the
// visible output (`generated`), whether generation is currently inside a
// constrained arithmetic span (`insideConstrainedOut`), and the active span
// contents (`currentConstrainedOut`).
//
// Outside spans, it generates freely so the model can write natural-language
// reasoning, but it watches for the visible delimiter token "<<". If that token
// is observed, it enters constrained mode with an empty parser-valid prefix.
// Inside spans, it uses parser-aware constrained decoding, preferring adaptive
// group-aware constrained steps when the caller supplies contextual token
// groups, and otherwise using a hard constrained step. As soon as the parser
// reports the arithmetic span complete, it emits the closing delimiter ">>" and
// returns to free generation.
//
// This state supports valid generation because only parser-valid constrained
// prefixes are stored in `currentConstrainedOut`, span entry always resets that
// prefix to `[]`, and span exit clears it again. The visible delimiters satisfy
// the task contract that arithmetic computations appear inside << >>.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
// - Outside-span branch: if the free token is not "<<", insideConstrainedOut
//   stays false so the implication remains vacuous. If the token is "<<", we
//   set insideConstrainedOut := true and currentConstrainedOut := [], and the
//   precondition gives parser.IsValidPrefix([]).
// - Complete-prefix branch: CloseConstrainedSpan exits constrained mode and
//   clears currentConstrainedOut, so the implication is vacuous afterward.
// - Active constrained branch: AdaptiveConstrainedStep and ConstrainedStep each
//   return either EOS or a token that preserves parser validity. On EOS we
//   break without changing state; otherwise AppendConstrainedToken extends both
//   generated and currentConstrainedOut with that parser-valid token, so
//   parser.IsValidPrefix(currentConstrainedOut) is preserved.
//
// progress:
// - Outside-span branch: UnconstrainedStep consumes 1 token-step. If EOS is
//   returned, visible output does not grow; otherwise at most one visible token
//   is appended, so |generated| increases by at most the consumed budget 1.
// - Complete-prefix branch: CloseConstrainedSpan consumes 1 token-step and
//   appends at most the visible delimiter token ">>", so the output-length
//   bound is preserved when steps increases by 1.
// - Active constrained branch: each constrained-step helper consumes 1
//   token-step. If EOS is returned, visible output does not grow; otherwise
//   AppendConstrainedToken appends exactly one visible token, so visible growth
//   is at most the consumed token budget. Thus |generated| <= |generatedPrefix|
//   + steps remains true in every branch.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(
  lm,
  "Solve the math word problem step by step. Every arithmetic computation must appear inside visible << >> delimiters."
);

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var next := eosToken;
    if |validTokenGroups| > 0 {
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    } else {
      next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    }
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

